            connect current_tempWstatus to mrm.current_tempWstatus;
        connection mrm_if : PortConnection
            connect interface_failure to mrm.interface_failure;
        connection mrm_intf : PortConnection
            connect internal_failure to mrm.internal_failure;
        connection mrm_mode : PortConnection
            connect mrm.regulator_mode to regulator_mode;

        attribute Domain: CASE_Scheduling::Domain = 4;

    }

